CREATE DATABASE IF NOT EXISTS campuscare CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE campuscare;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,department VARCHAR(120) NOT NULL DEFAULT '',role ENUM('student','admin') NOT NULL DEFAULT 'student',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_users_role_name(role,name));
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,category_name VARCHAR(80) NOT NULL UNIQUE,description TEXT);
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,department_name VARCHAR(120) NOT NULL UNIQUE,contact_person VARCHAR(120),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE complaints(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_id INT NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,location VARCHAR(180) NOT NULL,priority ENUM('Low','Medium','High','Urgent') NOT NULL DEFAULT 'Medium',status ENUM('Pending','In Progress','Resolved','Rejected') NOT NULL DEFAULT 'Pending',assigned_department VARCHAR(120),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_complaint_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_complaint_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,CONSTRAINT fk_complaint_department FOREIGN KEY(assigned_department) REFERENCES departments(department_name) ON UPDATE CASCADE ON DELETE SET NULL,INDEX idx_complaints_status(status),INDEX idx_complaints_priority(priority),INDEX idx_complaints_created(created_at),INDEX idx_complaints_user_created(user_id,created_at));
CREATE TABLE complaint_updates(id INT AUTO_INCREMENT PRIMARY KEY,complaint_id INT NOT NULL,admin_id INT,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,remarks TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_update_complaint FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE,CONSTRAINT fk_update_admin FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_updates_complaint_time(complaint_id,created_at));
CREATE OR REPLACE VIEW complaint_summary AS SELECT c.id,c.title,c.status,c.priority,c.location,c.created_at,u.name student,u.email,k.category_name category,c.assigned_department FROM complaints c INNER JOIN users u ON u.id=c.user_id INNER JOIN categories k ON k.id=c.category_id;
